import {goalMarkup} from './goals-view.js';
import { weightInsightMarkup } from './weight-insight.js';
import { strengthDialog } from './strength-entry.js';
export function journalView({data,windowChoice,graph,entry,kg,signed,day,escape,arrow,shown}){
 const m=data.metrics,canImport=data.canImport||data.local,source=r=>r.source==='manual'?'Manual entry':'MASS import';
 return `<main id="journal-main" class="jr-main jr-v2"><section class="jr-title"><div><h1>Journal</h1><p>Weight trends and gym sessions.</p></div><div class="jr-quick-actions">${data.canLog?'<a href="#quick-log" class="primary-button">Log a weigh-in</a>':canImport?'<a href="#mass-import" class="primary-button">Import MASS backup</a>':''}${data.canLogStrength?'<button type="button" id="log-strength" class="secondary-button">Log strength session</button>':''}</div></section>
 <p id="journal-status" class="jr-save-status" role="status"></p>
 <div class="jr-workspace"><div class="jr-history"><section class="jr-chart-section" aria-label="Weight history"><div class="jr-chart-heading"><h2>Weight trend</h2><div class="tr-window" role="group" aria-label="Journal window">${[['30','30 days'],['90','90 days'],['all','All history']].map(([key,label])=>`<button data-window="${key}" aria-pressed="${windowChoice===key}">${label}</button>`).join('')}</div></div>${graph()}</section>${data.cloud?goalMarkup(data.weightGoal,'weight'):''}${weightInsightMarkup(data)}
 <section class="jr-facts" aria-label="Weight summary"><div><span>Latest scale reading</span><strong>${kg(data.latestReading?.kg??m.latestKg)} <small>kg</small></strong><p>${data.latestReading?.dateKey?day(data.latestReading.dateKey):m.latestDate?day(m.latestDate):'Your first reading starts here'}</p></div><div><span>Smoothed trend</span><strong>${kg(data.trend?.latest?.trendKg??null)} <small>kg</small></strong><p>${data.trend?.lastObservedDate?'Last observed '+day(data.trend.lastObservedDate):'Your first reading starts here'}</p></div><div><span>Change in this window</span><strong>${signed(m.changeKg)} <small>kg</small></strong><p>${m.changeFrom&&m.changeKg!==null?day(m.changeFrom)+' → '+day(m.latestDate):'Two recorded days needed'}</p></div></section></div>
 <aside id="quick-log" class="jr-entry-panel" aria-label="Quick weigh-in">${entry}</aside></div>
 <section id="measurements" class="jr-measurements"><div class="tr-section-head"><div><h2>Weigh-ins</h2></div><p>${m.recordedDays} days · ${m.weighIns} readings</p></div><div class="jr-entry-list">${data.entries.length?data.entries.slice(0,shown).map(r=>`<article class="jr-entry-row"><button class="jr-date-button" data-date="${r.dateKey}" aria-label="Inspect ${day(r.dateKey)}">${day(r.dateKey)}<span>${source(r)}</span></button><div class="jr-entry-note">${r.note?escape(r.note):'<span>—</span>'}</div><strong>${kg(r.kg)}<small> kg</small></strong>${r.source==='manual'&&data.canLog?`<button class="secondary-button jr-edit" data-edit-weight="${escape(r.entryKey)}" aria-label="Edit ${kg(r.kg)} kg reading on ${day(r.dateKey)}">Edit</button>`:'<span class="jr-source-tag">MASS</span>'}</article>`).join(''):'<div class="jr-empty-small"><h3>No readings in this window.</h3><p>Log a reading or choose All history to see earlier entries.</p></div>'}</div>${data.entries.length>shown?`<button class="secondary-button" id="more-readings">Show more readings (${data.entries.length-shown} remaining)</button>`:''}
 ${data.removed?.length?`<details class="jr-removed"><summary>Removed entries (${data.removed.length})</summary>${data.removed.map(r=>`<div><span>${day(r.dateKey)} · ${kg(r.kg)} kg</span><button class="secondary-button" data-restore-weight="${escape(r.entryKey)}">Restore reading</button></div>`).join('')}</details>`:''}
 <details class="jr-method"><summary>How the chart is calculated</summary><p>${escape(data.method)}</p><p>Daily values average readings on that date. The trend uses a calendar-aware exponential average with a seven-day half-life, seeded from all available history. Between weigh-ins the chart interpolates that trend continuously. Dots and their stems show the actual readings; interpolated days are not stored as weigh-ins. After the latest weigh-in, a dashed line holds the last trend value without extrapolating a slope. Held and interpolated values are display estimates, never stored readings. The original entries and their sources stay separate. Change compares the first and last recorded daily values in the selected window.</p><p>Weight change alone does not establish a change in fitness or body composition. ${data.tombstones} source deletion markers are retained outside the active chart.</p></details></section>
 <section id="strength" class="jr-strength"><div class="tr-section-head"><div><h2>Gym sessions</h2></div><div class="se-list-actions"><p>${m.loggedSessions} logged sessions · ${m.recordedSessionMinutes} recorded min</p></div></div><div class="jr-strength-list">${data.sessions.length?data.sessions.map(s=>`<article class="jr-strength-row"><div class="jr-session-date"><span>${new Date(s.dateKey+'T12:00Z').getUTCDate()}</span><small>${new Date(s.dateKey+'T12:00Z').toLocaleDateString('en-AU',{month:'short',year:'numeric',timeZone:'UTC'})}</small></div><div><h3>${escape(s.focus)}</h3><span>${s.source==='manual'?'Manual entry':'MASS'} · ${escape(s.kind)}</span>${s.source==='manual'?`<p class="se-session-summary">${s.checkin?'Effort '+s.checkin.effort+'/10 · '+({planned:'As planned',modified:'Modified','cut-short':'Cut short'}[s.checkin.completion]):'Check-in not added'}</p><button type="button" class="text-button" data-edit-session="${escape(s.entryKey)}">${s.checkin?'View or edit session':'Add check-in or edit'}</button>`:''}${s.note?`<details><summary>Session note</summary><p>${escape(s.note)}</p></details>`:''}</div><strong>${s.mins===null?'—':s.mins}<small> min</small></strong></article>`).join(''):'<div class="jr-empty-small"><h3>No gym sessions yet</h3><p>Log a strength session or import your MASS backup.</p></div>'}</div>${data.removedSessions?.length?`<details class="jr-removed"><summary>Removed sessions (${data.removedSessions.length})</summary>${data.removedSessions.map(s=>`<div><span>${day(s.dateKey)} · ${escape(s.focus)}</span><button type="button" class="secondary-button" data-restore-session="${escape(s.entryKey)}">Restore session</button></div>`).join('')}</details>`:''}<p class="jr-section-note">MASS imports and manually logged sessions keep their sources. Exercise sets, loads and repetitions are not inferred.</p></section>
 <section id="mass-import" class="jr-import-panel" aria-label="Import and sources"><div><h2>MASS backup</h2><p>Import weigh-ins and gym sessions from a MASS export. Reimporting the same file will not add duplicates.</p><p class="jr-import-meta">${data.imports.length?'Last imported '+new Date(data.imports[0].importedAt).toLocaleDateString('en-AU'):'No MASS backup imported yet.'}</p></div><div>${canImport?`<button id="choose-file" class="secondary-button">Import MASS backup ${arrow}</button><input type="file" id="mass-file" accept=".json,application/json" hidden>`:'<p>Import is available in your private account or local library.</p>'}${data.cloud||data.local?`<a class="text-button" href="/api/export">Export your complete library ${arrow}</a>`:''}<p id="import-status" role="status"></p><p id="import-error" class="tr-error" role="alert"></p></div></section>
 <footer class="tr-footer"><span>MY FITNESS ANALYSER</span><p>${escape(data.scope)}</p><a href="/training">Back to training ${arrow}</a></footer></main>
 ${strengthDialog()}<dialog id="mass-review" aria-labelledby="review-title"><div class="jr-review-head"><button id="close-review" class="icon-button" aria-label="Close import review">×</button></div><div id="review-content"></div></dialog>`;
}
